// Bit-exact parity test for the fused-Metal MRoPE path (rope_fused.cpp)
// vs vectors generated by the REAL mlx_vlm modules with fused_apply=True
// (tools/gen_rope_fused_vectors.py). Compares raw bytes (view->uint32 /
// view->uint16), not tolerances.
//
// Standalone build (no CMake edits required):
//   MLXROOT=.venv/lib/python3.12/site-packages/mlx
//   xcrun clang++ -std=c++20 -O2 -I"$MLXROOT/include" -Icpp/engine/src \
//       cpp/engine/src/rope_fused.cpp cpp/engine/tests/test_rope_fused.cpp \
//       -L"$MLXROOT/lib" -lmlx -Wl,-rpath,"$(pwd)/$MLXROOT/lib" -o /tmp/test_rope_fused
//   /tmp/test_rope_fused cpp/engine/tests/vectors_rope_fused
#include "rope_fused.hpp"

#include <mlx/mlx.h>

#include <cstdint>
#include <cstdio>
#include <fstream>
#include <iterator>
#include <string>
#include <vector>

namespace mx = mlx::core;
using namespace veystrix::engine;

// Byte-for-byte comparison via raw-bit reinterpretation (view), not a numeric
// cast. float32 -> uint32 view; f16/bf16 -> uint16 view widened to uint32.
static bool bit_equal(const mx::array& a, const mx::array& b) {
  if (a.shape() != b.shape() || a.dtype() != b.dtype()) return false;
  auto bits = [](const mx::array& flat) -> mx::array {
    if (flat.dtype() == mx::float32) return mx::view(flat, mx::uint32);
    return mx::astype(mx::view(flat, mx::uint16), mx::uint32);
  };
  mx::array av = bits(mx::reshape(a, {-1}));
  mx::array bv = bits(mx::reshape(b, {-1}));
  mx::eval(av, bv);
  if (av.size() != bv.size()) return false;
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (std::size_t i = 0; i < av.size(); ++i)
    if (pa[i] != pb[i]) return false;
  return true;
}

static std::string get_str(const std::string& s, const std::string& key) {
  auto pos = s.find("\"" + key + "\"");
  if (pos == std::string::npos) return "";
  auto colon = s.find(':', pos);
  if (colon == std::string::npos) return "";
  std::size_t i = colon + 1;
  while (i < s.size() && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n')) ++i;
  if (i >= s.size() || s[i] != '"') return "";
  ++i;
  std::string out;
  for (; i < s.size() && s[i] != '"'; ++i) out += s[i];
  return out;
}

static double get_num(const std::string& s, const std::string& key) {
  auto pos = s.find("\"" + key + "\"");
  if (pos == std::string::npos) return 0.0;
  auto colon = s.find(':', pos);
  std::size_t i = colon + 1;
  while (i < s.size() && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n')) ++i;
  std::string num;
  for (; i < s.size(); ++i) {
    char c = s[i];
    if (c == ',' || c == '\n' || c == '}' || c == ' ' || c == '\t' ||
        c == '"') break;
    num += c;
  }
  return std::stod(num);
}

static bool get_bool(const std::string& s, const std::string& key) {
  auto pos = s.find("\"" + key + "\"");
  if (pos == std::string::npos) return false;
  auto t = s.find("true", pos);
  auto f = s.find("false", pos);
  if (t == std::string::npos) return false;
  if (f == std::string::npos) return true;
  return t < f;
}

static std::vector<int> get_int_list(const std::string& s,
                                     const std::string& key) {
  std::vector<int> out;
  auto pos = s.find("\"" + key + "\"");
  if (pos == std::string::npos) return out;
  auto lb = s.find('[', pos);
  auto rb = s.find(']', lb);
  if (lb == std::string::npos || rb == std::string::npos) return out;
  for (std::size_t i = lb + 1; i < rb;) {
    if (s[i] == '-' || (s[i] >= '0' && s[i] <= '9')) {
      std::size_t j = i;
      if (s[j] == '-') ++j;
      while (j < rb && s[j] >= '0' && s[j] <= '9') ++j;
      out.push_back(std::stoi(s.substr(i, j - i)));
      i = j;
    } else {
      ++i;
    }
  }
  return out;
}

static int run_case(const std::string& root, const std::string& name) {
  const std::string dir = root + "/" + name;
  auto load = [&](const char* n) { return mx::load(dir + "/" + n + ".npy"); };
  std::ifstream mf(dir + "/meta.json");
  std::string meta((std::istreambuf_iterator<char>(mf)),
                   std::istreambuf_iterator<char>());

  const std::string dtype_str = get_str(meta, "dtype");
  const bool stored_u16 = get_bool(meta, "stored_as_uint16");
  const int rotary_dim = static_cast<int>(get_num(meta, "rotary_dim"));

  mx::array q = load("q");
  mx::array k = load("k");
  mx::array q_out = load("q_out");
  mx::array k_out = load("k_out");
  if (stored_u16) {
    q = mx::view(q, mx::bfloat16);
    k = mx::view(k, mx::bfloat16);
    q_out = mx::view(q_out, mx::bfloat16);
    k_out = mx::view(k_out, mx::bfloat16);
  }
  mx::array positions = load("position_ids");
  mx::array inv_freq = load("inv_freq");
  mx::array selector = load("position_selector");
  mx::eval(q, k, positions, inv_freq, selector, q_out, k_out);

  // Also verify the inv_freq / selector helpers match production bit-for-bit.
  const float base = static_cast<float>(get_num(meta, "base"));
  const std::vector<int> section = get_int_list(meta, "mrope_section");
  mx::array inv_freq_cpp = rope_fused_compute_inv_freq(rotary_dim, base);
  mx::array selector_cpp =
      rope_fused_position_selector(section, rotary_dim / 2, true);
  mx::eval(inv_freq_cpp, selector_cpp);
  if (!bit_equal(inv_freq_cpp, inv_freq)) {
    std::fprintf(stderr, "[%s] inv_freq helper differs from production\n",
                 name.c_str());
    return 1;
  }
  if (!bit_equal(selector_cpp, selector)) {
    std::fprintf(stderr, "[%s] position_selector helper differs from production\n",
                 name.c_str());
    return 1;
  }

  mx::array q_got = rope_fused_apply(q, positions, inv_freq, selector,
                                     rotary_dim);
  mx::array k_got = rope_fused_apply(k, positions, inv_freq, selector,
                                     rotary_dim);
  mx::eval(q_got, k_got);

  if (!bit_equal(q_got, q_out)) {
    std::fprintf(stderr, "[%s] q rotated output differs (dtype=%s)\n",
                 name.c_str(), dtype_str.c_str());
    return 1;
  }
  if (!bit_equal(k_got, k_out)) {
    std::fprintf(stderr, "[%s] k rotated output differs (dtype=%s)\n",
                 name.c_str(), dtype_str.c_str());
    return 1;
  }
  std::printf("  [%s] OK (dtype=%s, pos_ndim=%d, %s, bit-identical)\n",
              name.c_str(), dtype_str.c_str(),
              static_cast<int>(get_num(meta, "position_ndim")),
              stored_u16 ? "bf16-bits" : "native");
  return 0;
}

int main(int argc, char** argv) {
  const std::string root =
      argc > 1 ? argv[1] : "cpp/engine/tests/vectors_rope_fused";
  std::ifstream f(root + "/cases.json");
  if (!f) {
    std::fprintf(stderr, "cases.json missing; run gen_rope_fused_vectors.py\n");
    return 2;
  }
  std::string text((std::istreambuf_iterator<char>(f)),
                   std::istreambuf_iterator<char>());
  std::vector<std::string> cases;
  std::size_t pos = 0;
  while ((pos = text.find("\"dir\"", pos)) != std::string::npos) {
    auto q1 = text.find('"', text.find(':', pos) + 1);
    auto q2 = text.find('"', q1 + 1);
    if (q1 != std::string::npos && q2 != std::string::npos)
      cases.push_back(text.substr(q1 + 1, q2 - q1 - 1));
    pos = q2;
  }
  if (cases.empty()) {
    std::fprintf(stderr, "no cases parsed\n");
    return 2;
  }
  int failed = 0;
  for (const auto& c : cases) failed += run_case(root, c);
  if (failed) {
    std::fprintf(stderr, "%d fused-RoPE case(s) FAILED\n", failed);
    return 1;
  }
  std::printf("test_rope_fused OK (%zu cases bit-identical to Python fused "
              "kernel)\n", cases.size());
  return 0;
}
